const concepts=[['Rain trails','Vertical tear trails','Fine vertical trails on a muted blue field.','Depression','#527493'],['Wave state','Rising and falling ribbons','Rising and falling ribbons in lilac and amber.','Bipolar','#785197'],['Branch out','Branching routes','Branching routes across lime and olive.','ADHD','#99a83f'],['Let it flow','Pressure and release','Pressure and release in oxblood and orange.','Anger regulation','#a12f38'],['On repeat','Returning loops','Returning taupe loops on warm ivory.','OCD','#b3a58d'],['New perspective','Shifted perspective','Shifted geometric perspectives on petrol green.','Delusional disorder','#245c53'],['Off the orbit','Offset fragments','Offset circular fragments in lavender and mint.','Schizophrenia','#a28ab4']];
const types=['Accent','Placement','Bold','All-over'];const products=concepts.flatMap((c,i)=>types.map((t,j)=>({id:i*4+j,c:i,t:j,name:c[3]+" — Type "+"ABCD"[j],price:32000+j*2000})));let filter='all',expanded=false,sort='featured',selected=null,chosenSize='M';let cart=[];try{cart=JSON.parse(localStorage.getItem('spanky-cart')||'[]').filter(r=>products.some(p=>p.id===r.id)&&['S','M','L','XL'].includes(r.size)&&Number.isInteger(r.qty)&&r.qty>0)}catch{}const $=s=>document.querySelector(s);const money=v=>'₩'+v.toLocaleString('en-US');const asset=p=>`assets/product-${p.c}-${p.t}.webp`;const pd=$('#productDialog'),cd=$('#cartDialog'),info=$('#infoDialog');
function save(){localStorage.setItem('spanky-cart',JSON.stringify(cart));$('#count').textContent=cart.reduce((a,r)=>a+r.qty,0)}
function render(){let list=products.filter(p=>filter==='all'||p.t===Number(filter));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(!expanded&&filter==='all'&&sort==='featured')list=[products[7],products[11],products[3],products[19],products[15],products[23],products[27],products[6]];$('#products').innerHTML=list.map(p=>`<article class="product"><div class="product-visual"><span class="tag">COLLECTION 01 / TYPE ${'ABCD'[p.t]}</span><button class="image-button" data-product="${p.id}" aria-label="${p.name} view details" style="border:0;background:none;width:100%;padding:0"><img src="${asset(p)}" alt="${p.name} ${types[p.t]} boxer brief" loading="lazy"></button><button class="quick" data-product="${p.id}" aria-label="${p.name} choose options">+</button></div><div class="product-title"><h3><button data-product="${p.id}" style="border:0;background:none;padding:0;text-align:left;font-weight:700">${p.name}</button></h3><span class="price">${money(p.price)}</span></div><p class="product-sub">BOXER BRIEF · TYPE ${'ABCD'[p.t]} / ${types[p.t]}</p><div class="swatches"><span class="swatch" style="--c:${concepts[p.c][4]}"></span><span style="font-size:9px;color:#777">S – XL</span></div></article>`).join('');$('#more').hidden=filter!=='all'||expanded||sort!=='featured';}
function detail(id,reset=true){selected=products.find(p=>p.id===id);if(reset)chosenSize='M';const p=selected,c=concepts[p.c];$('#productDetail').innerHTML=`<div class="detail"><div class="detail-image"><img src="${asset(p)}" alt="${p.name} product concept"></div><div><div class="eyebrow">COLLECTION 01 / ${c[1].toUpperCase()}</div><h2>${p.name}</h2><b>${money(p.price)}</b><p>${c[2]}<br>An artistic interpretation of the ${c[3]} collection concept, not a universal description of a diagnosis.</p><div class="label">GRAPHIC / TYPE ${'ABCD'[p.t]}</div><div class="choices">${types.map((t,i)=>`<button data-type="${i}" class="${i===p.t?'selected':''}">${'ABCD'[i]}</button>`).join('')}</div><div class="label">SIZE <button data-guide style="float:right;border:0;background:none;text-decoration:underline;font-size:10px">Size guide ↗</button></div><div class="choices">${['S','M','L','XL'].map(s=>`<button data-size="${s}" class="${s===chosenSize?'selected':''}">${s}</button>`).join('')}</div><button class="button green full" id="add">Add to bag <span>+</span></button><p>Design concept. Prices and sizes are illustrative.<br>Final pattern placement and production specifications may vary.</p></div></div>`;if(!pd.open)pd.showModal()}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function cartView(){const subtotal=cart.reduce((a,r)=>a+products[r.id].price*r.qty,0);$('#cartContent').innerHTML=`<div class="eyebrow">YOUR FIRST LAYER</div><h2>Your bag <span style="color:var(--violet)">(${cart.reduce((a,r)=>a+r.qty,0)})</span></h2>${cart.length?cart.map((r,i)=>{const p=products[r.id];return `<div class="cart-row"><img src="${asset(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p>TYPE ${'ABCD'[p.t]} · ${r.size} / ${money(p.price)}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${r.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Increase quantity">+</button></div></div><div>${money(p.price*r.qty)}<br><button class="remove" data-remove="${i}">Remove</button></div></div>`}).join('')+`<div class="total"><span>Subtotal</span><b>${money(subtotal)}</b></div><p class="sample-note">Demo order only. No payment or shipping takes place.</p><button id="checkout" class="button green full">Checkout <span>↗</span></button>`:`<p style="padding:45px 0">Your bag is empty. Find a pattern that speaks to you.</p><button class="button full" id="continue">Continue shopping ↗</button>`}`;if(!cd.open)cd.showModal()}
function guide(){ $('#infoContent').innerHTML='<div class="eyebrow">FIND YOUR FIT</div><h2>Size guide</h2><table><tr><th>Size</th><th>Waist (cm)</th></tr><tr><td>S</td><td>68–76</td></tr><tr><td>M</td><td>76–84</td></tr><tr><td>L</td><td>84–92</td></tr><tr><td>XL</td><td>92–100</td></tr></table><p class="notice">Illustrative sizing for this concept. Final garment measurements will be confirmed before retail release.</p>';info.showModal()}
function checkout(){ $('#cartContent').innerHTML=`<div class="eyebrow">ONE STEP CLOSER</div><h2>Checkout</h2><p class="notice">Demo checkout. Use sample details only. No payment, order transmission or shipping takes place. Delivery information is not saved.</p><form id="orderForm"><div class="checkout-grid"><label>Recipient<input name="name" required maxlength="40" placeholder="Sample customer" autocomplete="off"></label><label>Email<input name="email" type="email" required placeholder="test@example.com" autocomplete="off"></label><label>Phone<input name="phone" type="tel" required pattern="[0-9+() -]{7,20}" placeholder="010-0000-0000" autocomplete="off"></label><label>Postal code<input name="zip" required pattern="[0-9]{5}" placeholder="00000" autocomplete="off"></label><label class="wide">Street address<input name="address" required maxlength="200" placeholder="Sample street address" autocomplete="off"></label><label class="wide">Address line 2<input name="detail" maxlength="100" placeholder="Apartment or suite (optional)" autocomplete="off"></label></div><div class="total"><span>Total · Free shipping (demo)</span><b>${money(cart.reduce((a,r)=>a+products[r.id].price*r.qty,0))}</b></div><label style="display:block;font-size:12px;margin-top:25px"><input type="checkbox" required> I understand this is a demo order, not a purchase.</label><button class="button green full" type="submit">Place demo order <span>↗</span></button><button type="button" id="backBag" class="load">Back to bag</button></form>`}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.classList.contains('close'))return b.closest('dialog').close();if(b.dataset.product!==undefined)return detail(Number(b.dataset.product));if(b.dataset.filter!==undefined){filter=b.dataset.filter;expanded=false;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()}if(b.dataset.type!==undefined)detail(selected.c*4+Number(b.dataset.type),false);if(b.dataset.size){chosenSize=b.dataset.size;detail(selected.id,false)}if(b.hasAttribute('data-guide')||b.id==='sizeGuide')guide();if(b.id==='add'){const row=cart.find(r=>r.id===selected.id&&r.size===chosenSize);if(row)row.qty++;else cart.push({id:selected.id,size:chosenSize,qty:1});save();pd.close();toast('Added to your bag.')}if(b.id==='bag')cartView();if(b.id==='more'){expanded=true;render()}if(b.dataset.qty!==undefined){const i=Number(b.dataset.qty);cart[i].qty+=Number(b.dataset.delta);if(cart[i].qty<=0)cart.splice(i,1);save();cartView()}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);save();cartView()}if(b.id==='checkout')checkout();if(b.id==='backBag')cartView();if(b.id==='continue'){cd.close();document.querySelector('#shop').scrollIntoView({behavior:'smooth'})}if(b.id==='shipping'){$('#infoContent').innerHTML='<h2>Shipping & returns</h2><p class="notice">SPANKY is currently a design project storefront. Products and orders are for demonstration only; no purchases or shipping take place.</p><p>Shipping times, costs, hygiene-related returns, seller details and customer support will be confirmed before retail release.</p>';info.showModal()}});
document.addEventListener('submit',e=>{if(e.target.id!=='orderForm')return;e.preventDefault();if(!cart.length)return cartView();const id='SP-DEMO-'+crypto.randomUUID().slice(0,8).toUpperCase();const total=cart.reduce((a,r)=>a+products[r.id].price*r.qty,0);$('#cartContent').innerHTML=`<div class="success"><div class="check">✳</div><div class="eyebrow">YOUR MOOD IS IN THE BAG</div><h2>Demo order complete!</h2><p>${id}</p><p>Order total ${money(total)}</p><p class="notice">You have completed the demo checkout.<br>No payment was taken, order transmitted, email sent or shipment arranged.</p><button class="button green" id="continue">Keep exploring ↗</button></div>`;cart=[];save()});$('#sort').addEventListener('change',e=>{sort=e.target.value;render()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));save();render();
if(new URLSearchParams(location.search).get('bag')==='1')cartView();
